{"text": "def rolling_mean(values, window=3):
    """The mean of each run of `window` values."""
    if window < 1:
        raise ValueError("window must be at least 1")
    out = []
    for i in range(len(values) - window + 1):
        out.append(sum(values[i:i + window]) / window)
    return out
